using Microsoft.Data.Sqlite; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed record StoredTaskEvent(Guid EventId,Guid ProjectId,Guid TaskId,Guid? ExecutionId,string Type,string Payload,DateTimeOffset CreatedAt);
public sealed class TaskEventRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AppendAsync(StoredTaskEvent e,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT OR IGNORE INTO task_events(id,project_id,task_id,execution_id,event_type,payload_json,created_at) VALUES($i,$p,$t,$x,$y,$z,$a)";q.Parameters.AddWithValue("$i",e.EventId.ToString());q.Parameters.AddWithValue("$p",e.ProjectId.ToString());q.Parameters.AddWithValue("$t",e.TaskId.ToString());q.Parameters.AddWithValue("$x",(object?)e.ExecutionId?.ToString()??DBNull.Value);q.Parameters.AddWithValue("$y",e.Type);q.Parameters.AddWithValue("$z",e.Payload);q.Parameters.AddWithValue("$a",e.CreatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct);} public async Task<IReadOnlyList<StoredTaskEvent>> ListAsync(Guid project,Guid task,int limit,CancellationToken ct=default){if(limit<=0)throw new ArgumentOutOfRangeException(nameof(limit));await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="SELECT id,project_id,task_id,execution_id,event_type,payload_json,created_at FROM task_events WHERE project_id=$p AND task_id=$t ORDER BY created_at,id LIMIT $l";q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",task.ToString());q.Parameters.AddWithValue("$l",limit);await using var r=await q.ExecuteReaderAsync(ct);var list=new List<StoredTaskEvent>();while(await r.ReadAsync(ct))list.Add(new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),Guid.Parse(r.GetString(2)),r.IsDBNull(3)?null:Guid.Parse(r.GetString(3)),r.GetString(4),r.GetString(5),DateTimeOffset.Parse(r.GetString(6))));return list;}}
